def upgrade():
    for card_id, patch in _CARDS.items():
        j = json.dumps(patch, ensure_ascii=False).replace("'", "''")
        op.execute(
            f"UPDATE pak_fault_cards "
            f"SET better_option_estimate = COALESCE(better_option_estimate, '{{}}'::jsonb) || '{j}'::jsonb "
            f"WHERE card_id = {card_id}"
        )


def downgrade():
    fields = [
        "description_good", "why_recommended_good", "description", "why_recommended",
        "description_best_comprehensive", "why_recommended_best_comprehensive",
        "description_best_replacement", "why_recommended_best_replacement",
        "description_good_en", "why_recommended_good_en", "description_en",
        "why_recommended_en", "description_best_comprehensive_en",
        "why_recommended_best_comprehensive_en", "description_best_replacement_en",
        "why_recommended_best_replacement_en", "description_good_ur",
        "why_recommended_good_ur", "description_ur", "why_recommended_ur",
        "description_best_comprehensive_ur", "why_recommended_best_comprehensive_ur",
        "description_best_replacement_ur", "why_recommended_best_replacement_ur"
    ]
    for f in fields:
        op.execute(f"UPDATE pak_fault_cards SET better_option_estimate = better_option_estimate - '{f}'")
